/**
 * Premium system.
 * - Premium is attached to a server (guild), like most public music bots.
 * - Keys are generated by bot owners (/genkey) after a purchase and redeemed
 *   with /redeem or from the web panel. Only a SHA-256 hash of each key is stored.
 */
const crypto = require('node:crypto');
const { premium: store } = require('./db');
const brand = require('../../bot.config');

const DAY = 86_400_000;

const TIERS = {
    free: {
        id: 'free', name: 'Free', rank: 0,
        queueLimit: 100, maxVolume: 100, filters: false, alwaysOn: false,
        playlists: 0, playlistSize: 0, autoplay: false
    },
    premium: {
        id: 'premium', name: 'Premium', rank: 1,
        queueLimit: 500, maxVolume: 150, filters: true, alwaysOn: true,
        playlists: 10, playlistSize: 200, autoplay: true
    },
    plus: {
        id: 'plus', name: 'Premium+', rank: 2,
        queueLimit: 2000, maxVolume: 200, filters: true, alwaysOn: true,
        playlists: 50, playlistSize: 1000, autoplay: true
    }
};

const hash = code => crypto.createHash('sha256').update(code.trim().toUpperCase()).digest('hex');

function newCode() {
    const part = () => crypto.randomBytes(3).toString('hex').toUpperCase().slice(0, 4);
    return `${brand.keyPrefix}-${part()}-${part()}-${part()}`;
}

/** Returns the active premium record for a guild (expired records fall back to free). */
function getGuild(guildId, now = Date.now()) {
    const rec = store.data.guilds[guildId];
    if (!rec || (rec.expiresAt && rec.expiresAt < now)) {
        return { tier: TIERS.free, expiresAt: null, active: false };
    }
    return { tier: TIERS[rec.tier] || TIERS.free, expiresAt: rec.expiresAt, active: true, redeemedBy: rec.redeemedBy };
}

const tierOf = guildId => getGuild(guildId).tier;

/** Creates `count` keys for `tier`, valid for `days` (0 = lifetime). Returns plain codes (shown once). */
function generateKeys({ tier, days, count = 1, createdBy }) {
    if (!TIERS[tier] || tier === 'free') throw new Error('Unknown tier');
    const codes = [];
    for (let i = 0; i < count; i++) {
        const code = newCode();
        store.data.keys[hash(code)] = { tier, days, createdBy, createdAt: Date.now(), usedBy: null, usedAt: null, guildId: null };
        codes.push(code);
    }
    store.save();
    return codes;
}

/** Redeems a key on a guild. Same tier stacks time, higher tier upgrades. */
function redeem({ code, guildId, userId, now = Date.now() }) {
    const key = store.data.keys[hash(String(code || ''))];
    if (!key) return { ok: false, error: 'That key does not exist. Check for typos.' };
    if (key.usedBy) return { ok: false, error: 'That key has already been redeemed.' };

    const current = store.data.guilds[guildId];
    const stillActive = current && (!current.expiresAt || current.expiresAt > now);
    const base = stillActive && current.tier === key.tier && current.expiresAt ? current.expiresAt : now;
    if (stillActive && !current.expiresAt && TIERS[current.tier].rank >= TIERS[key.tier].rank) {
        return { ok: false, error: `This server already has lifetime ${TIERS[current.tier].name}.` };
    }
    const expiresAt = key.days ? base + key.days * DAY : null;

    store.data.guilds[guildId] = { tier: key.tier, expiresAt, redeemedBy: userId, since: now };
    Object.assign(key, { usedBy: userId, usedAt: now, guildId });
    store.save();
    return { ok: true, tier: TIERS[key.tier], expiresAt };
}

function revoke(guildId) {
    delete store.data.guilds[guildId];
    store.save();
}

/** Counts for the panel / owner stats. */
function summary(now = Date.now()) {
    const guilds = Object.values(store.data.guilds).filter(g => !g.expiresAt || g.expiresAt > now);
    const keys = Object.values(store.data.keys);
    return {
        activeServers: guilds.length,
        byTier: { premium: guilds.filter(g => g.tier === 'premium').length, plus: guilds.filter(g => g.tier === 'plus').length },
        keysUnused: keys.filter(k => !k.usedBy).length
    };
}

module.exports = { TIERS, getGuild, tierOf, generateKeys, redeem, revoke, summary, hash };
